CREATE TABLE "chats" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "guid" TEXT NOT NULL UNIQUE, "chat_identifier" TEXT NULL, "service_name" TEXT NULL, "group_id" TEXT NULL, "original_group_id" TEXT NULL, "legacy_group_ids_json" TEXT NULL, "latest_group_title" TEXT NULL, "thread_key" TEXT NULL, "is_archived" INTEGER NULL CHECK ("is_archived" IN (0, 1)), "mute_type" TEXT NULL, "mute_args" TEXT NULL, "is_pinned" INTEGER NULL CHECK ("is_pinned" IN (0, 1)), "has_unread_message" INTEGER NULL CHECK ("has_unread_message" IN (0, 1)), "display_name" TEXT NULL, "is_filtered_as_spam" INTEGER NULL CHECK ("is_filtered_as_spam" IN (0, 1)), "auto_send_read_receipts" INTEGER NULL CHECK ("auto_send_read_receipts" IN (0, 1)), "auto_send_typing_indicators" INTEGER NULL CHECK ("auto_send_typing_indicators" IN (0, 1)), "text_field_text" TEXT NULL, "text_field_attachments_json" TEXT NOT NULL DEFAULT '[]', "latest_message_id" INTEGER NULL, "latest_message_date_us" INTEGER NULL, "date_deleted_us" INTEGER NULL, "style" INTEGER NULL, "lock_chat_name" INTEGER NOT NULL DEFAULT 0 CHECK ("lock_chat_name" IN (0, 1)), "lock_chat_icon" INTEGER NOT NULL DEFAULT 0 CHECK ("lock_chat_icon" IN (0, 1)), "last_read_message_guid" TEXT NULL, "custom_theme_light" TEXT NULL, "custom_theme_dark" TEXT NULL, "wallpaper_type" TEXT NULL, "dynamic_wallpaper_id" TEXT NULL, "dynamic_wallpaper_config" TEXT NULL, "custom_avatar_path" TEXT NULL, "custom_background_path" TEXT NULL, "pin_index" INTEGER NULL);
CREATE TABLE "messages" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "original_rowid" INTEGER NULL, "guid" TEXT NULL UNIQUE, "handle_id" INTEGER NULL, "other_handle" INTEGER NULL, "text" TEXT NULL, "subject" TEXT NULL, "country" TEXT NULL, "service" TEXT NULL, "date_created_us" INTEGER NULL, "sort_at_us" INTEGER NOT NULL, "date_read_us" INTEGER NULL, "date_delivered_us" INTEGER NULL, "is_from_me" INTEGER NULL CHECK ("is_from_me" IN (0, 1)), "has_dd_results" INTEGER NULL CHECK ("has_dd_results" IN (0, 1)), "date_played_us" INTEGER NULL, "item_type" INTEGER NULL, "group_title" TEXT NULL, "group_action_type" INTEGER NULL, "balloon_bundle_id" TEXT NULL, "associated_message_guid" TEXT NULL, "associated_message_part" INTEGER NULL, "associated_message_type" TEXT NULL, "expressive_send_style_id" TEXT NULL, "has_attachments" INTEGER NOT NULL CHECK ("has_attachments" IN (0, 1)), "has_reactions" INTEGER NOT NULL CHECK ("has_reactions" IN (0, 1)), "date_deleted_us" INTEGER NULL, "thread_originator_guid" TEXT NULL, "thread_originator_part" TEXT NULL, "big_emoji" INTEGER NULL CHECK ("big_emoji" IN (0, 1)), "error" INTEGER NOT NULL, "chat_id" INTEGER NULL, "attributed_body_json" TEXT NULL, "message_summary_info_json" TEXT NULL, "payload_data_json" TEXT NULL, "metadata_json" TEXT NULL, "has_apple_payload_data" INTEGER NOT NULL CHECK ("has_apple_payload_data" IN (0, 1)), "date_edited_us" INTEGER NULL, "was_delivered_quietly" INTEGER NOT NULL CHECK ("was_delivered_quietly" IN (0, 1)), "did_notify_recipient" INTEGER NOT NULL CHECK ("did_notify_recipient" IN (0, 1)), "is_bookmarked" INTEGER NOT NULL CHECK ("is_bookmarked" IN (0, 1)), "is_delivered" INTEGER NOT NULL CHECK ("is_delivered" IN (0, 1)), "handle_relation_id" INTEGER NULL, "error_message" TEXT NULL, "has_effect_played" INTEGER NOT NULL CHECK ("has_effect_played" IN (0, 1)), "apple_chat_guid" TEXT NULL);
CREATE TABLE "handles" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "original_rowid" INTEGER NULL, "address" TEXT NOT NULL, "country" TEXT NULL, "color" TEXT NULL, "default_phone" TEXT NULL, "default_email" TEXT NULL, "formatted_address" TEXT NULL, "unique_address_and_service" TEXT NOT NULL UNIQUE, "service" TEXT NOT NULL);
CREATE TABLE "chat_handles" ("chat_id" INTEGER NOT NULL, "handle_id" INTEGER NOT NULL, PRIMARY KEY ("chat_id", "handle_id")) WITHOUT ROWID;
CREATE TABLE "attachments" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "original_rowid" INTEGER NULL, "guid" TEXT NULL UNIQUE, "uti" TEXT NULL, "mime_type" TEXT NULL, "is_outgoing" INTEGER NULL CHECK ("is_outgoing" IN (0, 1)), "transfer_name" TEXT NULL, "total_bytes" INTEGER NULL, "height" INTEGER NULL, "width" INTEGER NULL, "web_url" TEXT NULL, "message_id" INTEGER NULL, "has_live_photo" INTEGER NOT NULL CHECK ("has_live_photo" IN (0, 1)), "is_downloaded" INTEGER NOT NULL CHECK ("is_downloaded" IN (0, 1)), "metadata_json" TEXT NULL, "exif_json" TEXT NULL);
CREATE TABLE "contacts" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "display_name" TEXT NOT NULL, "native_contact_id" TEXT NOT NULL UNIQUE, "avatar_path" TEXT NULL, "addresses_json" TEXT NOT NULL, "nickname" TEXT NULL, "first_name" TEXT NULL, "last_name" TEXT NULL, "middle_name" TEXT NULL, "name_prefix" TEXT NULL, "name_suffix" TEXT NULL, "company" TEXT NULL, "phone_numbers_json" TEXT NULL, "email_addresses_json" TEXT NULL, "is_native" INTEGER NOT NULL CHECK ("is_native" IN (0, 1)));
CREATE TABLE "contact_handles" ("contact_id" INTEGER NOT NULL, "handle_id" INTEGER NOT NULL, PRIMARY KEY ("contact_id", "handle_id")) WITHOUT ROWID;
CREATE TABLE "custom_groups" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL UNIQUE, "sort_order" INTEGER NOT NULL, "show_unread_badge" INTEGER NOT NULL CHECK ("show_unread_badge" IN (0, 1)));
CREATE TABLE "custom_group_chats" ("group_id" INTEGER NOT NULL, "chat_id" INTEGER NOT NULL, PRIMARY KEY ("group_id", "chat_id")) WITHOUT ROWID;
CREATE TABLE "storage_meta" ("key" TEXT NOT NULL, "value" TEXT NULL, PRIMARY KEY ("key"));
CREATE TABLE "copy_checkpoints" ("entity" TEXT NOT NULL, "last_source_id" INTEGER NOT NULL, "rows_copied" INTEGER NOT NULL, PRIMARY KEY ("entity"));
CREATE INDEX messages_timeline ON messages (chat_id, sort_at_us, id) WHERE associated_message_guid IS NULL AND date_deleted_us IS NULL;
CREATE INDEX messages_chat_time ON messages (chat_id, sort_at_us, id);
CREATE INDEX messages_assoc ON messages (associated_message_guid) WHERE associated_message_guid IS NOT NULL;
CREATE INDEX messages_thread ON messages (thread_originator_guid) WHERE thread_originator_guid IS NOT NULL;
CREATE INDEX messages_handle_id ON messages (handle_id);
CREATE INDEX messages_handle_rel ON messages (handle_relation_id);
CREATE INDEX messages_bookmarked ON messages (chat_id, sort_at_us) WHERE is_bookmarked = 1;
CREATE INDEX attachments_message ON attachments (message_id);
CREATE INDEX chats_list ON chats (latest_message_date_us DESC, id DESC) WHERE date_deleted_us IS NULL;
CREATE INDEX chats_identifier ON chats (chat_identifier);
CREATE INDEX chats_thread_key ON chats (thread_key) WHERE thread_key IS NOT NULL;
CREATE INDEX handles_rowid ON handles (original_rowid);
CREATE INDEX handles_address ON handles (address, service);
CREATE INDEX chat_handles_handle ON chat_handles (handle_id);
CREATE INDEX contact_handles_handle ON contact_handles (handle_id);
CREATE INDEX custom_group_chats_chat ON custom_group_chats (chat_id);
